//! 本机同用户Unix socket接口。写操作用一次性预览凭证，不能由模型直接授权。
use crate::{schedule,UiEvent};
use serde_json::{json,Value};
use std::{collections::HashMap,fs,io::{BufRead,BufReader,Read,Write},os::unix::{fs::{FileTypeExt,MetadataExt,PermissionsExt},io::AsRawFd,net::{UnixListener,UnixStream}},path::PathBuf,sync::{mpsc::{self,Sender},Arc,Mutex},time::{Duration,Instant}};
use tao::event_loop::EventLoopProxy;
#[derive(Clone,Default)]pub struct Hub{listeners:Arc<Mutex<Vec<Sender<Value>>>>}
pub fn broadcast(hub:&Hub,value:&Value){if let Ok(mut listeners)=hub.listeners.lock(){listeners.retain(|tx|tx.send(value.clone()).is_ok());}}
fn path()->PathBuf{PathBuf::from(std::env::var_os("HOME").unwrap_or_default()).join("Library/Application Support/KaruoCleaner/control.sock")}
const COMMANDS:&[&str]=&["goal_analyze","goal_analysis_status","purge_preview","space_goal_get","space_goal_save","smart_clean","smart_clean_status","ready","rules_get","root_set","volumes","session_get","scan","scan_page","cancel","space_start","space_browse","ignore_get","ignore_add","ignore_remove","schedule_get","schedule_save","guardian_get","guardian_save","history","restore","purge","move","optimize","terminate","startup_get","startup_set","login_settings","reveal","ai_chat","ai_proposal_plan","space_cleanup_plan","cleanup_plan_page","cleanup_analyze","cleanup_apply","undo_last","ai_get","ai_save","ai_models","ai_analyze","uninstall_plan","uninstall_analyze","uninstall_apply"];
const WRITES:&[&str]=&["smart_clean","move","restore","purge","terminate","startup_set","uninstall_apply","cleanup_apply","undo_last"];
pub fn capabilities()->Value{json!({"transport":"unix_socket_same_uid","commands":COMMANDS,"destructive_commands":WRITES,"protocol":"--api JSON 或 --api - 从stdin读取JSON；读命令直接返回，启动扫描返回queued后用session_get查询；写操作preview再apply且confirmed=true；保护规则不会被绕过","socket":path(),"network_listen":false})}
fn random_id()->Result<String,String>{let mut b=[0u8;16];fs::File::open("/dev/urandom").and_then(|mut f|f.read_exact(&mut b)).map_err(|_|"无法产生本机确认凭证")?;Ok(b.iter().map(|n|format!("{n:02x}")).collect())}
fn expected(cmd:&str)->&'static str{match cmd{"goal_analyze"|"goal_analysis_status"=>"goal_analysis","purge_preview"=>"purge_preview","space_goal_get"|"space_goal_save"=>"space_goal","smart_clean"|"smart_clean_status"=>"smart_clean","guardian_get"|"guardian_save"=>"guardian","ai_chat"=>"ai_chat","ai_proposal_plan"=>"proposal_dynamic","space_cleanup_plan"|"cleanup_plan_page"=>"cleanup_plan","cleanup_analyze"=>"ai_result","cleanup_apply"=>"moved","undo_last"=>"undo","rules_get"=>"rules","root_set"=>"root","ready"=>"ready","session_get"=>"session","scan_page"=>"scan_page","volumes"=>"volumes","space_browse"=>"space_view","ignore_get"|"ignore_add"|"ignore_remove"=>"ignore","schedule_get"|"schedule_save"=>"schedule","history"|"restore"|"purge"=>"history","move"|"uninstall_apply"=>"moved","optimize"=>"apps","startup_get"|"startup_set"=>"startup","ai_get"|"ai_save"|"ai_models"=>"ai_config","ai_analyze"|"uninstall_analyze"=>"ai_result","uninstall_plan"=>"uninstall_plan",_=>"message"}}
type Previews=Arc<Mutex<HashMap<String,(Instant,Value)>>>;
pub fn start(proxy:EventLoopProxy<UiEvent>)->Result<Hub,String>{
    let path=path();schedule::safe_path(&path.with_extension("owner.json"))?;fs::create_dir_all(path.parent().unwrap()).map_err(|_|"无法建立本机控制目录")?;
    if let Ok(m)=fs::symlink_metadata(&path){if !m.file_type().is_socket()||m.uid()!=unsafe{libc::geteuid()}{return Err("本机接口路径不是本用户socket，未覆盖".into())}if UnixStream::connect(&path).is_ok(){return Err("已有应用实例持有控制接口".into())}fs::remove_file(&path).map_err(|_|"无法移除已退出实例的socket")?;}
    let listener=UnixListener::bind(&path).map_err(|_|"无法监听本机控制接口")?;fs::set_permissions(&path,fs::Permissions::from_mode(0o600)).map_err(|_|"无法限制本机接口权限")?;let hub=Hub::default();let transport=hub.clone();let previews:Previews=Arc::new(Mutex::new(HashMap::new()));let serial=Arc::new(Mutex::new(()));
    std::thread::spawn(move ||{for stream in listener.incoming().flatten(){let hub=transport.clone();let proxy=proxy.clone();let previews=previews.clone();let serial=serial.clone();std::thread::spawn(move ||{let mut stream=stream;let response=(||{let mut uid=0;let mut gid=0;if unsafe{libc::getpeereid(stream.as_raw_fd(),&mut uid,&mut gid)}!=0||uid!=unsafe{libc::geteuid()}{return Err("仅允许本机同一用户访问".into())}stream.set_read_timeout(Some(Duration::from_secs(5))).map_err(|_|"无法设置读取期限")?;
        let mut line=String::new();BufReader::new(stream.try_clone().map_err(|_|"连接读取失败")?).take(1024*1024+1).read_line(&mut line).map_err(|_|"请求读取失败")?;if line.len()>1024*1024{return Err("单次API请求过大，请使用分类选择或分页".into())}let mut request:Value=serde_json::from_str(&line).map_err(|_|"请求不是JSON对象")?;let cmd=request["cmd"].as_str().ok_or("请求缺少cmd")?.to_owned();
        if cmd=="capabilities"{return Ok(capabilities())}
        if cmd=="preview"{let action=request["action"].clone();let operation=action["cmd"].as_str().ok_or("预览缺少action.cmd")?;if !WRITES.contains(&operation){return Err("此命令不需要删除确认凭证".into())}let token=random_id()?;let mut p=previews.lock().map_err(|_|"确认凭证暂不可用")?;p.retain(|_,(at,_)|at.elapsed()<Duration::from_secs(300));p.insert(token.clone(),(Instant::now(),action.clone()));return Ok(json!({"preview_id":token,"action":action,"expires_in_seconds":300,"warning":"这是待执行请求，不表示已清理。执行时仍逐项验证扫描身份、保护名单、占用和真实路径；永久删除保留本机确认。"}))}
        if cmd=="apply"{if request["confirmed"]!=true{return Err("需要明确confirmed=true并提供有效preview_id".into())}let token=request["preview_id"].as_str().ok_or("缺少preview_id")?;let (at,action)=previews.lock().map_err(|_|"确认凭证暂不可用")?.remove(token).ok_or("确认凭证无效、已使用或应用已重启")?;if at.elapsed()>Duration::from_secs(300){return Err("确认凭证已过期，请重新预览".into())}request=action;request["api_confirmed"]=json!(true);}else{if WRITES.contains(&cmd.as_str()){return Err("写操作需先preview，再apply一次性凭证".into())}if let Some(o)=request.as_object_mut(){o.remove("api_confirmed");}}
        let cmd=request["cmd"].as_str().ok_or("缺少执行命令")?.to_owned();if !COMMANDS.contains(&cmd.as_str()){return Err("未知命令，使用capabilities查看接口".into())}
        if cmd=="ai_chat"&&request["chat_request_id"].is_null(){request["chat_request_id"]=json!(random_id()?);}
        let chat_request_id=request["chat_request_id"].clone();
        // 普通API读回串行；AI有独立回执编号，不持有API队列等待模型。扫描不等待结束。
        let _guard=if cmd=="ai_chat"{None}else{Some(serial.lock().map_err(|_|"本机API正忙")?)};let (tx,rx)=mpsc::channel();hub.listeners.lock().map_err(|_|"事件接口不可用")?.push(tx);let module=request["module"].as_str().map(str::to_owned);proxy.send_event(UiEvent::Request(request)).map_err(|_|"应用事件循环已退出")?;
        if ["goal_analyze","smart_clean","scan","space_start","cancel","login_settings","reveal"].contains(&cmd.as_str()){return Ok(json!({"queued":true,"cmd":cmd,"module":module,"note":"已入队，不代表完成；请通过session_get或实际文件/历史回读结果"}))}
        let event=expected(&cmd);let start=Instant::now();loop{let remain=Duration::from_secs(70).saturating_sub(start.elapsed());if remain.is_zero(){return Err("本机请求等待超时，请先查询状态再决定重试".into())}let value=rx.recv_timeout(remain).map_err(|_|"本机响应超时，请先查询状态再决定重试")?;let name=value["event"].as_str().unwrap_or_default();if cmd=="ai_chat"&&(name!="ai_chat"||value["chat_request_id"]!=chat_request_id){continue}if name=="message"{return Ok(value)}if (name==event||(event=="proposal_dynamic"&&["cleanup_plan","uninstall_plan","ai_schedule_proposal","ai_restore_proposal"].contains(&name))) && module.as_ref().is_none_or(|m|value["module"].as_str().is_none_or(|v|v==m)){return Ok(value)}}
    })();let value=response.unwrap_or_else(|e:String|json!({"error":e,"executed":false}));if let Ok(bytes)=serde_json::to_vec(&value){let _=stream.write_all(&bytes);let _=stream.write_all(b"\n");}});}});Ok(hub)
}
pub fn client(request:&Value)->Result<Value,String>{
    if request["cmd"]=="capabilities"{return Ok(capabilities())}
    let mut stream=UnixStream::connect(path()).map_err(|_|"本机应用未运行或接口尚未就绪，请先打开轻理AI")?;stream.set_read_timeout(Some(Duration::from_secs(75))).map_err(|_|"无法设置响应期限")?;let bytes=serde_json::to_vec(request).map_err(|_|"请求格式无效")?;stream.write_all(&bytes).and_then(|_|stream.write_all(b"\n")).map_err(|_|"无法发送本机请求")?;let mut response=String::new();BufReader::new(stream).read_line(&mut response).map_err(|_|"响应读取失败或超时，先查询状态不要盲目重试")?;serde_json::from_str(&response).map_err(|_|"接口响应格式无效".into())
}
